package com.droptracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

/**
 * Correlates an explicit inventory "Drop" click with the subsequent decrease in
 * inventory quantity. This avoids counting a click that did not actually remove the item.
 * Package-private so the state machine can be unit tested without a RuneLite client.
 */
final class DropConfirmationTracker
{
    private static final int PENDING_TIMEOUT_TICKS = 5;

    private final List<PendingDrop> pending = new ArrayList<>();
    private Map<Integer, Integer> previousCounts = Collections.emptyMap();
    private int gameTick;

    void queue(int itemId, String itemName, int expectedQuantity, long unitPrice, long timestamp,
        Map<Integer, Integer> currentCounts)
    {
        queue(itemId, itemName, expectedQuantity, unitPrice, 0L, timestamp, currentCounts);
    }

    void queue(int itemId, String itemName, int expectedQuantity, long unitPrice, long highAlchPrice,
        long timestamp, Map<Integer, Integer> currentCounts)
    {
        if (itemId <= 0 || expectedQuantity <= 0)
        {
            return;
        }
        if (pending.isEmpty())
        {
            previousCounts = normalizedCopy(currentCounts);
        }
        pending.add(new PendingDrop(itemId, itemName, expectedQuantity, unitPrice, highAlchPrice, timestamp,
            gameTick + PENDING_TIMEOUT_TICKS));
    }

    List<DropRecord> inventoryChanged(Map<Integer, Integer> currentCounts)
    {
        Map<Integer, Integer> current = normalizedCopy(currentCounts);
        Map<Integer, Integer> losses = new HashMap<>();
        for (Map.Entry<Integer, Integer> before : previousCounts.entrySet())
        {
            int after = current.getOrDefault(before.getKey(), 0);
            if (before.getValue() > after)
            {
                losses.put(before.getKey(), before.getValue() - after);
            }
        }
        previousCounts = current;
        expireOldPending();
        if (pending.isEmpty() || losses.isEmpty())
        {
            return Collections.emptyList();
        }

        List<DropRecord> confirmed = new ArrayList<>();
        for (Map.Entry<Integer, Integer> loss : losses.entrySet())
        {
            int remainingLoss = loss.getValue();
            Iterator<PendingDrop> iterator = pending.iterator();
            while (iterator.hasNext() && remainingLoss > 0)
            {
                PendingDrop candidate = iterator.next();
                if (candidate.itemId != loss.getKey())
                {
                    continue;
                }
                int confirmedQuantity = Math.min(candidate.expectedQuantity, remainingLoss);
                if (confirmedQuantity > 0)
                {
                    confirmed.add(new DropRecord(candidate.itemId, candidate.itemName, confirmedQuantity,
                        candidate.unitPrice, candidate.highAlchPrice, candidate.timestamp));
                    remainingLoss -= confirmedQuantity;
                }
                iterator.remove();
            }
        }
        confirmed.sort(Comparator.comparingLong(DropRecord::getTimestamp));
        return confirmed;
    }

    void gameTick()
    {
        gameTick++;
        expireOldPending();
    }

    void reset(Map<Integer, Integer> currentCounts)
    {
        pending.clear();
        previousCounts = normalizedCopy(currentCounts);
    }

    private void expireOldPending()
    {
        pending.removeIf(drop -> gameTick > drop.expiresAfterTick);
    }

    private static Map<Integer, Integer> normalizedCopy(Map<Integer, Integer> input)
    {
        Map<Integer, Integer> result = new HashMap<>();
        if (input != null)
        {
            for (Map.Entry<Integer, Integer> entry : input.entrySet())
            {
                Integer id = entry.getKey();
                Integer quantity = entry.getValue();
                if (id != null && id > 0 && quantity != null && quantity > 0)
                {
                    result.put(id, quantity);
                }
            }
        }
        return result;
    }

    private static final class PendingDrop
    {
        private final int itemId;
        private final String itemName;
        private final int expectedQuantity;
        private final long unitPrice;
        private final long highAlchPrice;
        private final long timestamp;
        private final int expiresAfterTick;

        private PendingDrop(int itemId, String itemName, int expectedQuantity, long unitPrice,
            long highAlchPrice, long timestamp, int expiresAfterTick)
        {
            this.itemId = itemId;
            this.itemName = itemName;
            this.expectedQuantity = expectedQuantity;
            this.unitPrice = Math.max(0L, unitPrice);
            this.highAlchPrice = Math.max(0L, highAlchPrice);
            this.timestamp = timestamp;
            this.expiresAfterTick = expiresAfterTick;
        }
    }
}

package com.droptracker;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Aggregates confirmed item drops into one all-time row per item ID. */
final class DropHistoryAggregator
{
    private DropHistoryAggregator()
    {
    }

    /**
     * Collapse imported or previously saved rows into one cumulative record per item.
     * DropRecord.merge preserves accumulated value totals and the latest drop timestamp.
     */
    static List<DropRecord> aggregateByItem(Collection<DropRecord> input)
    {
        Map<Integer, DropRecord> aggregated = new LinkedHashMap<>();
        if (input != null)
        {
            for (DropRecord record : input)
            {
                if (record == null || !record.isValid())
                {
                    continue;
                }
                DropRecord previous = aggregated.get(record.getItemId());
                aggregated.put(record.getItemId(), previous == null ? record : previous.merge(record));
            }
        }

        List<DropRecord> result = new ArrayList<>(aggregated.values());
        sortByLatestDrop(result);
        return result;
    }

    /** Add a newly confirmed drop to the item's lifetime aggregate, creating a row only if needed. */
    static void addOrMerge(List<DropRecord> history, DropRecord incoming)
    {
        if (incoming == null || !incoming.isValid())
        {
            return;
        }
        for (int i = 0; i < history.size(); i++)
        {
            DropRecord existing = history.get(i);
            if (existing.getItemId() == incoming.getItemId())
            {
                history.set(i, existing.merge(incoming));
                sortByLatestDrop(history);
                return;
            }
        }
        history.add(incoming);
        sortByLatestDrop(history);
    }

    private static void sortByLatestDrop(List<DropRecord> records)
    {
        records.sort(Comparator.comparingLong(DropRecord::getTimestamp)
            .thenComparingInt(DropRecord::getItemId));
    }
}

package com.droptracker;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.util.Filepath;

/** Versioned, atomic JSON persistence for locally recorded drops. */
public final class DropHistoryStore
{
    private static final String HISTORY_FILE_NAME = "dropped-items.json";
    private static final int CURRENT_SCHEMA_VERSION = 1;
    private static final long MAX_IMPORT_BYTES = 25L * 1024L * 1024L;
    private static final int MAX_IMPORT_RECORDS = 100_000;

    private final Filepath directory;
    private final Filepath file;
    private final Gson gson;

    public DropHistoryStore(Filepath directory, Gson gson)
    {
        this.directory = directory;
        this.file = directory.joinSegment(HISTORY_FILE_NAME);
        // Preserve RuneLite's registered Gson adapters while formatting user-readable JSON.
        this.gson = gson.newBuilder().setPrettyPrinting().create();
    }

    /**
     * Read a user-selected export without changing or quarantining the source file.
     * Imports are strict: reject malformed documents or records instead of silently
     * importing only part of the user's data.
     */
    public synchronized List<DropRecord> readImport(Filepath source) throws IOException
    {
        if (source == null || !source.isFile())
        {
            throw new IOException("The selected import file does not exist or is not a regular file.");
        }
        if (source.size() > MAX_IMPORT_BYTES)
        {
            throw new IOException("The selected JSON file is too large to import safely.");
        }

        final HistoryDocument document;
        try (Reader reader = source.openReader())
        {
            document = gson.fromJson(reader, HistoryDocument.class);
        }
        catch (JsonParseException | IllegalStateException e)
        {
            throw new IOException("The selected file is not valid Drop Tracker JSON.", e);
        }

        if (document == null)
        {
            throw new IOException("The selected JSON file is empty.");
        }
        if (document.schemaVersion != CURRENT_SCHEMA_VERSION)
        {
            throw new IOException("Unsupported Drop Tracker JSON schema version: " + document.schemaVersion
                + ". This version supports schema " + CURRENT_SCHEMA_VERSION + ".");
        }
        if (document.records == null)
        {
            throw new IOException("The JSON file is missing its records array.");
        }
        if (document.records.size() > MAX_IMPORT_RECORDS)
        {
            throw new IOException("The JSON file contains too many records to import safely.");
        }

        List<DropRecord> result = new ArrayList<>();
        for (int i = 0; i < document.records.size(); i++)
        {
            DropRecord record = document.records.get(i);
            if (record == null || !record.isValid())
            {
                throw new IOException("Invalid drop record at index " + i + "; no data was imported.");
            }
            result.add(record);
        }
        return result;
    }

    /** Export records using the same versioned JSON format used for local persistence. */
    public synchronized void exportTo(Filepath destination, List<DropRecord> records) throws IOException
    {
        if (destination == null)
        {
            throw new IOException("No export destination was selected.");
        }
        if (destination.equals(file))
        {
            throw new IOException("Choose a different file so the local history cannot be overwritten by an export.");
        }

        directory.createDirectories();
        Filepath temporary = directory.createTempFile("export-", ".tmp");
        try
        {
            writeDocument(temporary, records);
            // The chooser returns a rooted Filepath for the selected destination. Copying through
            // Filepath keeps the write within the user-approved selection and avoids raw Path I/O.
            temporary.copyTo(destination, StandardCopyOption.REPLACE_EXISTING);
        }
        finally
        {
            temporary.deleteIfExists();
        }
    }

    /** Delete the local history file. The next confirmed drop will create it again. */
    public synchronized void delete() throws IOException
    {
        file.deleteIfExists();
    }

    public synchronized List<DropRecord> load() throws IOException
    {
        if (!file.exists())
        {
            return new ArrayList<>();
        }

        final HistoryDocument document;
        try (Reader reader = file.openReader())
        {
            document = gson.fromJson(reader, HistoryDocument.class);
        }
        catch (JsonParseException | IllegalStateException e)
        {
            quarantineCorruptFile(e);
            return new ArrayList<>();
        }

        if (document == null)
        {
            quarantineCorruptFile(new IOException("History JSON was empty"));
            return new ArrayList<>();
        }
        if (document.schemaVersion > CURRENT_SCHEMA_VERSION)
        {
            throw new IOException("History schema " + document.schemaVersion
                + " is newer than this plugin supports; refusing to overwrite it");
        }

        List<DropRecord> result = new ArrayList<>();
        if (document.records != null)
        {
            for (DropRecord record : document.records)
            {
                if (record != null && record.isValid())
                {
                    result.add(record);
                }
            }
        }
        return result;
    }

    public synchronized void save(List<DropRecord> records) throws IOException
    {
        directory.createDirectories();
        Filepath temporary = directory.createTempFile("history-", ".tmp");
        try
        {
            writeDocument(temporary, records);
            try
            {
                temporary.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            }
            catch (AtomicMoveNotSupportedException e)
            {
                temporary.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
            }
        }
        finally
        {
            temporary.deleteIfExists();
        }
    }

    private void writeDocument(Filepath destination, List<DropRecord> records) throws IOException
    {
        HistoryDocument document = new HistoryDocument();
        document.schemaVersion = CURRENT_SCHEMA_VERSION;
        document.records = new ArrayList<>();
        if (records != null)
        {
            for (DropRecord record : records)
            {
                if (record != null && record.isValid())
                {
                    document.records.add(record);
                }
            }
        }

        try (Writer writer = destination.openWriter(
            StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE))
        {
            gson.toJson(document, writer);
            writer.write(System.lineSeparator());
        }
    }

    private void quarantineCorruptFile(Exception original) throws IOException
    {
        Filepath quarantine = directory.joinSegment(
            file.getFileName() + ".corrupt-" + Instant.now().toEpochMilli());
        try
        {
            file.moveTo(quarantine, StandardCopyOption.REPLACE_EXISTING);
        }
        catch (IOException moveFailure)
        {
            moveFailure.addSuppressed(original);
            throw new IOException("History could not be read and could not be preserved at " + quarantine,
                moveFailure);
        }
    }

    private static final class HistoryDocument
    {
        // Intentionally no field initializers: imports must prove these fields were present.
        // Local loading remains backward-tolerant for older files that omitted a schema version.
        private int schemaVersion;
        private List<DropRecord> records;
    }
}

package com.droptracker;

import java.util.Objects;

/** Cumulative aggregate for one item deliberately dropped by the player; timestamp is the latest drop. */
public final class DropRecord
{
    private int itemId;
    private String itemName;
    private long quantity;
    private long unitPrice;
    private long highAlchPrice;
    private long timestamp;

    // Nullable so histories created by older versions can still calculate totals from unit price * quantity.
    private Long recordedGeTotal;
    private Long recordedHighAlchTotal;

    // Required by Gson.
    public DropRecord()
    {
    }

    /** Backward-compatible constructor for older tests and version-1 JSON records. */
    public DropRecord(int itemId, String itemName, long quantity, long unitPrice, long timestamp)
    {
        this(itemId, itemName, quantity, unitPrice, 0L, timestamp);
    }

    public DropRecord(int itemId, String itemName, long quantity, long unitPrice, long highAlchPrice, long timestamp)
    {
        this(itemId, itemName, quantity, unitPrice, highAlchPrice, timestamp,
            multiplySaturated(quantity, unitPrice), multiplySaturated(quantity, highAlchPrice));
    }

    private DropRecord(int itemId, String itemName, long quantity, long unitPrice, long highAlchPrice,
        long timestamp, long recordedGeTotal, long recordedHighAlchTotal)
    {
        if (itemId <= 0)
        {
            throw new IllegalArgumentException("itemId must be positive");
        }
        if (quantity <= 0)
        {
            throw new IllegalArgumentException("quantity must be positive");
        }
        if (unitPrice < 0)
        {
            throw new IllegalArgumentException("unitPrice cannot be negative");
        }
        if (highAlchPrice < 0)
        {
            throw new IllegalArgumentException("highAlchPrice cannot be negative");
        }
        if (timestamp < 0)
        {
            throw new IllegalArgumentException("timestamp cannot be negative");
        }
        if (recordedGeTotal < 0 || recordedHighAlchTotal < 0)
        {
            throw new IllegalArgumentException("recorded totals cannot be negative");
        }
        this.itemId = itemId;
        this.itemName = Objects.requireNonNull(itemName, "itemName");
        this.quantity = quantity;
        this.unitPrice = unitPrice;
        this.highAlchPrice = highAlchPrice;
        this.timestamp = timestamp;
        this.recordedGeTotal = recordedGeTotal;
        this.recordedHighAlchTotal = recordedHighAlchTotal;
    }

    public int getItemId()
    {
        return itemId;
    }

    public String getItemName()
    {
        return itemName == null ? "Unknown item" : itemName;
    }

    public long getQuantity()
    {
        return quantity;
    }

    /** Most recently observed nonzero GE unit price for this item. */
    public long getUnitPrice()
    {
        return unitPrice;
    }

    /** RuneLite's item-definition high-alchemy value per item. */
    public long getHighAlchPrice()
    {
        return highAlchPrice;
    }

    public long getTimestamp()
    {
        return timestamp;
    }

    /** Sum of the estimated GE value captured across all confirmed drops of this item. */
    public long getTotalValue()
    {
        return recordedGeTotal != null ? Math.max(0L, recordedGeTotal)
            : multiplySaturated(quantity, unitPrice);
    }

    /** Estimated high-alchemy value for the accumulated quantity of this item. */
    public long getTotalHighAlchValue()
    {
        return recordedHighAlchTotal != null ? Math.max(0L, recordedHighAlchTotal)
            : multiplySaturated(quantity, highAlchPrice);
    }

    /** Combine two cumulative/incremental records for the same item across all time. */
    public DropRecord merge(DropRecord other)
    {
        Objects.requireNonNull(other, "other");
        if (itemId != other.itemId)
        {
            throw new IllegalArgumentException("Only records for the same item can be merged");
        }

        long mergedQuantity = addSaturated(quantity, other.quantity);
        long mergedGeTotal = addSaturated(getTotalValue(), other.getTotalValue());
        // High-alch value is item-definition data, so recompute it for the combined quantity.
        // This also fills the value for older records created before high-alch was stored.
        long latestHaPrice = other.highAlchPrice > 0 ? other.highAlchPrice : highAlchPrice;
        long mergedHaTotal = multiplySaturated(mergedQuantity, latestHaPrice);
        boolean otherIsNewer = other.timestamp >= timestamp;
        long latestGePrice = otherIsNewer
            ? (other.unitPrice > 0 ? other.unitPrice : unitPrice)
            : (unitPrice > 0 ? unitPrice : other.unitPrice);
        String preferredName = otherIsNewer ? other.itemName : itemName;
        String fallbackName = otherIsNewer ? itemName : other.itemName;
        String latestName = preferredName == null || preferredName.trim().isEmpty()
            ? (fallbackName == null || fallbackName.trim().isEmpty() ? getItemName() : fallbackName)
            : preferredName;

        return new DropRecord(itemId, latestName, mergedQuantity, latestGePrice, latestHaPrice,
            Math.max(timestamp, other.timestamp), mergedGeTotal, mergedHaTotal);
    }

    /** Recalculate high-alchemy value from current RuneLite item metadata without changing GE totals. */
    public DropRecord withHighAlchPrice(long newHighAlchPrice)
    {
        long safePrice = Math.max(0L, newHighAlchPrice);
        return new DropRecord(itemId, getItemName(), quantity, unitPrice, safePrice, timestamp,
            getTotalValue(), multiplySaturated(quantity, safePrice));
    }

    public boolean isValid()
    {
        return itemId > 0 && itemName != null && !itemName.trim().isEmpty()
            && quantity > 0 && unitPrice >= 0 && highAlchPrice >= 0 && timestamp >= 0
            && (recordedGeTotal == null || recordedGeTotal >= 0)
            && (recordedHighAlchTotal == null || recordedHighAlchTotal >= 0);
    }

    private static long multiplySaturated(long left, long right)
    {
        if (left <= 0 || right <= 0)
        {
            return 0L;
        }
        if (left > Long.MAX_VALUE / right)
        {
            return Long.MAX_VALUE;
        }
        return left * right;
    }

    private static long addSaturated(long left, long right)
    {
        if (right > 0 && left > Long.MAX_VALUE - right)
        {
            return Long.MAX_VALUE;
        }
        return left + right;
    }
}

package com.droptracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("droptracker")
public interface DropTrackerConfig extends Config
{
    @Range(min = 100, max = 100000)
    @ConfigItem(
        keyName = "historyLimit",
        name = "History entries",
        description = "Maximum number of distinct item rows retained locally",
        position = 0
    )
    default int historyLimit()
    {
        return 10000;
    }

    @Range(min = 10, max = 18)
    @ConfigItem(
        keyName = "fontSize",
        name = "Panel font size",
        description = "Font size used by the Drop Tracker panel (10–18 pt)",
        position = 1
    )
    default int fontSize()
    {
        return 15;
    }

    @ConfigItem(
        keyName = "showSummaryTotals",
        name = "Show summary totals",
        description = "Show total item count, quantity, GE value, and high-alchemy value at the top",
        position = 2
    )
    default boolean showSummaryTotals()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showQuantity",
        name = "Show quantity",
        description = "Show the cumulative quantity for each item",
        position = 3
    )
    default boolean showQuantity()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showGrandExchangeValue",
        name = "Show GE value",
        description = "Show estimated Grand Exchange value",
        position = 4
    )
    default boolean showGrandExchangeValue()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showHighAlchValue",
        name = "Show high-alchemy value",
        description = "Show estimated high-alchemy value",
        position = 5
    )
    default boolean showHighAlchValue()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showLastDropped",
        name = "Show last dropped date",
        description = "Show the most recent drop date and time in day/month/year format",
        position = 6
    )
    default boolean showLastDropped()
    {
        return true;
    }

    @ConfigItem(
        keyName = "ignoredItemIds",
        name = "Ignore item IDs",
        description = "Comma-separated item IDs that should not be tracked when dropped (for example: 995, 554)",
        position = 7
    )
    default String ignoredItemIds()
    {
        return "";
    }
    @ConfigItem(
        keyName = "skipWarnings",
        name = "Skip destructive-action warnings",
        description = "When enabled, skip confirmation dialogs for deleting history, removing item history, and replacing imported data",
        position = 8
    )
    default boolean skipWarnings()
    {
        return false;
    }

}

package com.droptracker;

